use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── A: the conversion route is a PER-CALL economics decision — one
        // dequant pass amortized across the batch (prefill-sized converts,
        // decode keeps the in-place quantized read), the f16 copy lives in
        // the graph POOL sized by the ACTUAL KV length (never a load-time
        // n_ctx reserve), every reserve-assuming site learns the pool path,
        // and the in-place fast kernel's supported-predicate REFUSES the
        // armed route so the two can never both hold for one call. ──
        KernelRule {
            rule_id: "prefill-batch-pool-f16-conversion-sized-by-actual-length".to_string(),
            gpu_concept: "MECHANISM (batch-shaped dequant-conversion route with the copy living in the graph pool; category A — memory access/staging): flash-attention over a quantized K/V cache has two reads — the in-place quantized walk the decode MMA kernel serves, and an f16 copy that unlocks the f16 MMA kernel — and the commit makes the choice a PER-CALL function of the batch's amortization economics, with the copy's MEMORY HOME the load-bearing half. The route's own contract, verbatim (fattn-common.cuh:53-56): '// GGML_CUDA_FA_PREFILL_F16=N: prefill-sized batches (more than 8 queries) over a quantized K/V cache of at most N cells' + '// convert K/V to f16 in pool memory sized by the actual KV length and run the f16 MMA kernel; decode keeps the in-place' + '// quantized read. Nothing is reserved at load (the reserved f16 copy would be n_ctx cells).' then 'static inline bool ggml_cuda_fattn_prefill_f16(const ggml_tensor * dst)'. THE ADMISSION IS THE ECONOMICS, verbatim (fattn-common.cuh:64): 'return max_kv > 0 && Q->ne[1] > 8 && K->ne[1] <= max_kv && K->type == V->type && ggml_is_quantized(K->type);' — one dequant pass over the cache is amortized across Q->ne[1] queries, so the boundary is the query count (> 8), not an arch cap; max_kv is the opt-in env knob (GGML_CUDA_FA_PREFILL_F16=N, default 0 — commit: 'Off by default.') and doubles as the MEMORY BUDGET (K->ne[1] <= max_kv: an unbounded context would blow the pool copy past the cells it is allowed). WHERE THE COPY LIVES — the POOL, sized by the ACTUAL length, never a load-time reserve: verbatim (fattn-common.cuh:1019), '// GGML_CUDA_FA_PREFILL_F16: the f16 copies come from the pool, not from the space reserved behind dst'; the copy allocates at call time, verbatim (fattn-common.cuh:1044), 'half * K_f16 = prefill_f16 ? K_f16_pool.alloc(ggml_nelements(K)) : (half *) f16_extra.K;' (V likewise :1078) — ggml_nelements is the live cell count, so a workload pays a copy proportional to what it used, where a load-time reserve is n_ctx cells unconditionally ('the reserved f16 copy would be n_ctx cells') — steady-state zero cost when the shape never fires is what makes the lever free. EVERY SITE THAT ASSUMED THE RESERVE LEARNS THE POOL: the f16_extra fetch is negated, verbatim (fattn-common.cuh:1022), 'ggml_cuda_flash_attn_ext_get_f16_extra_data(KQV, need_f16_K && !prefill_f16, need_f16_V && !prefill_f16);', and the allocation accounting treats pool-backed as nothing, verbatim (fattn.cu:583-587 get_alloc_size), 'if (ggml_cuda_fattn_mma_kv_native_supported(dst) || ggml_cuda_fattn_prefill_f16(dst)) { // In-place quantized K/V kernel, or f16 copies taken from the pool: nothing to reserve beyond dst.' THE DISJOINTNESS GUARD — the in-place fast kernel must REFUSE the armed route or it reads the quantized cache the route just converted away from, verbatim (fattn-mma-f16.cuh:2151-2152, inside ggml_cuda_fattn_mma_kv_native_supported, fn at :2133): 'if (ggml_cuda_fattn_prefill_f16(dst)) { return false; }' — the refusal rides the SAME query-count conjunct (the route needs > 8 queries; the in-place decode path serves the small-query shapes), so the two routes can never both hold for one call. THE COMMIT'S OWN SUMMARY, verbatim: 'Decode keeps the in-place quantized read. The f16 copies are sized by the actual KV length and nothing is reserved at load. Off by default.' DECISION CONTENT: (a) a batch-shaped conversion decision amortizes one dequant pass across the whole batch — prefill-sized (Q->ne[1] > 8) converts, decode keeps the in-place quantized read — the boundary predicate is the amortization economics, not an arch cap; (b) the opportunistic copies live in the graph POOL sized by ACTUAL KV length (ggml_nelements), NEVER a load-time reserve — the n_ctx-shaped reserve is the naive form this rule deletes; (c) every site that assumed the reserve path must learn the pool path — the f16_extra fetch negated (need_f16_K && !prefill_f16) and the alloc accounting reading 'nothing to reserve beyond dst'; (d) the in-place fast kernel's supported-predicate must REFUSE when the conversion route armed — disjoint by the same query-count conjunct, so both routes can never hold for one call. CLASS SIGNATURE: a per-call route choice between an in-place quantized read and a converted f16 copy, keyed on batch size + cache length + pool availability. REGIME: quantized K/V caches with bursty prefill (prompt processing) on kernels with an f16 fast path. ANTI-REGIME: steady decode (conversion would never amortize); unbounded context (the pool copy exceeds the memory budget — the N ceiling is the budget knob); K/V type mismatch (one converter serves one type — the K->type == V->type conjunct). KINSHIP (do not double-count): lossy-route-physical-error-bar-from-noise-floor (B242, entries_gpu_99) owns the ERROR-BAR face of lossy conversions — the gate pricing a lossy route's noise floor; THIS owns the MEMORY/AMORTIZATION economics face (WHEN to convert, WHERE the copy lives, WHAT may be reserved) — the f16 conversion here is a dequant of exactly-representable values, so no error bar is owed; the two compose, neither covers the other. Corpus greps over src/domains/kernel_opt/corpus/ for 'pool|prefill|f16 conv|dequant once|amortiz': dequant-once-per-k-tile-into-shared-memory (gpu_01) owns the INTRA-KERNEL dequant-once face (per-K-tile smem staging consumed across output rows of ONE GEMM — no route choice, no pool, no budget axis); row-tile-amortize-input-load (gpu_01) amortizes INPUT BANDWIDTH across output rows (M-widening — a different resource); pool-buffer-aliasing-dedicated-output (gpu_01) meets the pool as a HAZARD-TRACKING surface (aliased input/output handles → dedicated output + copy-back — not a conversion home); offload-cpu-bottleneck-to-gpu-kernel and chunk-split-mean-pool (gpu_01) hit 'pool' in the allocator/mean-pooling senses. ZERO owners of the batch-amortized pool-conversion route choice. prompt-form-refused-toolchain-format-gap-reopen-trigger (B242, entries_gpu_98) is UNRELATED (toolchain-gap negative rows). NotBenchable here (no numbers in the commit; the lever is opt-in default-off — the decision content is the route economics; our lane would gate the trigger on our own serving shapes). Source: PrismML-Eng/llama.cpp @ 25f68a426978a8c496f288900448b0d96be975aa #330 (MIT, prism tag prism-b10787-73bfe6c) — ggml/src/ggml-cuda/fattn-common.cuh:53-64,1019-1022,1044,1078 + ggml/src/ggml-cuda/fattn-mma-f16.cuh:2133,2148,2151-2152 + ggml/src/ggml-cuda/fattn.cu:583-587 at the pin. Batch 261 / Plan 265 / Research 297.".to_string(),
            ref_shape: "// naive: the always-reserve route — the f16 conversion's memory is\n// reserved at LOAD, sized by the context cap (2 x CTX cells for K + V),\n// paid unconditionally whether or not a prefill-sized batch ever arrives;\n// the other naive pole (no reserve) re-dequantizes the whole cache on\n// EVERY decode call. Neither cost is a function of the actual KV length\n// x call structure: one is a function of the CAP, the other of the CALL\n// COUNT.\nconst CTX: usize = 512; // n_ctx — the reserve is sized by THIS\nconst USED_KV: usize = 96; // the KV length the workload actually reaches\nconst NQ: usize = 4; // quantized codes per cell\nconst PREFILL_Q: usize = 16; // a prefill-sized batch (> 8)\nconst DECODE_STEPS: usize = 24;\n\nfn cell_scale(cell: usize) -> f32 {\n    // dyadic scales — every dequant product is exact in f32 AND f16\n    match cell % 3 {\n        0 => 0.25,\n        1 => 0.5,\n        _ => 1.0,\n    }\n}\n\nfn code(cell: usize, i: usize) -> f32 {\n    (((cell * 5 + i * 3) % 15) as i32) as f32\n}\n\nfn dequant(cell: usize, i: usize) -> f32 {\n    code(cell, i) * cell_scale(cell)\n}\n\nstruct Ledger {\n    reserved_cells: usize,  // f16 cells held from LOAD time (K + V)\n    converted_cells: usize, // dequant+store cell touches\n}\n\n/// pole 1: reserve 2 x n_ctx f16 cells at load; the first prefill burst\n/// converts into the reserved space; decode reads in place.\nfn always_reserve_route(prefill_bursts: usize) -> Ledger {\n    Ledger {\n        reserved_cells: 2 * CTX,\n        converted_cells: prefill_bursts * 2 * USED_KV,\n    }\n}\n\n/// pole 2: no reserve — convert the whole cache on EVERY call (including\n/// every decode step).\nfn per_call_conversion_route(prefill_bursts: usize) -> Ledger {\n    Ledger {\n        reserved_cells: 0,\n        converted_cells: (prefill_bursts + DECODE_STEPS) * 2 * USED_KV,\n    }\n}\n\n#[test]\nfn the_workload_is_prefill_sized_over_a_real_cache() {\n    assert!(PREFILL_Q > 8, \"the route's amortization boundary is > 8 queries\");\n    assert!(USED_KV < CTX, \"the workload's cache is a fraction of the cap\");\n    // the dequant values are the baseline both routes must reproduce\n    assert_eq!(dequant(0, 0).to_bits(), 0.0f32.to_bits());\n    for cell in 0..USED_KV {\n        for i in 0..NQ {\n            let v = dequant(cell, i);\n            assert_eq!(v, code(cell, i) * cell_scale(cell));\n            assert!(v.is_finite());\n        }\n    }\n}\n\n#[test]\nfn the_reserve_is_sized_by_the_context_cap_not_the_workload() {\n    let l = always_reserve_route(1);\n    assert_eq!(l.reserved_cells, 2 * CTX, \"load-time reserve = n_ctx cells, K + V\");\n    let actual_need = 2 * USED_KV; // what the peak actually holds\n    assert_eq!(actual_need, 192);\n    assert!(\n        l.reserved_cells as f64 / actual_need as f64 > 5.0,\n        \"over 5x reserved for what the workload uses\"\n    );\n    // the reserve is paid even if the prefill burst never arrives — it is\n    // a function of the cap, not of any call\n    assert_eq!(always_reserve_route(0).reserved_cells, 2 * CTX);\n}\n\n#[test]\nfn the_two_naive_poles_pay_cap_or_call_count_never_usage() {\n    let burst = always_reserve_route(1);\n    assert_eq!(burst.converted_cells, 2 * USED_KV, \"one burst: one pass\");\n    // decode steps read in place — but the reserve was still paid at load\n    let decode_only = always_reserve_route(0);\n    assert_eq!(decode_only.converted_cells, 0);\n    assert_eq!(decode_only.reserved_cells, 2 * CTX, \"the load-time cost is unconditional\");\n    // pole 2: every decode step re-dequantizes the whole cache\n    let per_call = per_call_conversion_route(1);\n    assert_eq!(per_call.converted_cells, (1 + DECODE_STEPS) * 2 * USED_KV);\n    assert_eq!(per_call.converted_cells, 25 * 192);\n}\n".to_string(),
            opt_pattern: "// optimized: the pool-conversion route — the admission IS the economics\n// (fattn-common.cuh:64): the env knob max_kv arms it (0 = off by default),\n// the query count > 8 is the amortization boundary, K->ne[1] <= max_kv is\n// the memory budget, K-type == V-type + quantized is the converter's\n// contract. Armed, ONE dequant pass converts K + V into POOL memory sized\n// by the ACTUAL cell count; decode keeps the in-place quantized read; the\n// in-place fast kernel's supported-predicate refuses when the route armed\n// (disjoint by the same query-count conjunct); the alloc accounting reads\n// 'nothing to reserve beyond dst' and the f16_extra fetch is negated.\nconst USED_KV: usize = 96;\nconst NQ: usize = 4;\nconst PREFILL_Q: usize = 16;\nconst DECODE_STEPS: usize = 24;\nconst CTX: usize = 512; // the cap-sized reserve, for the comparison only\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum KvType {\n    Q4_0,\n    Q8_0,\n    F16,\n}\n\nfn is_quantized(t: KvType) -> bool {\n    t != KvType::F16\n}\n\nfn cell_scale(cell: usize) -> f32 {\n    match cell % 3 {\n        0 => 0.25,\n        1 => 0.5,\n        _ => 1.0,\n    }\n}\n\nfn code(cell: usize, i: usize) -> f32 {\n    (((cell * 5 + i * 3) % 15) as i32) as f32\n}\n\nfn dequant(cell: usize, i: usize) -> f32 {\n    code(cell, i) * cell_scale(cell)\n}\n\n/// f16-exactness for the fixture's dyadic values (multiples of 0.25 under\n/// 2048 are exactly representable) — the pool copy stores the SAME values.\nfn f16_store(x: f32) -> f32 {\n    let q = (x * 4.0).round() / 4.0;\n    assert_eq!(q, x, \"fixture values must be f16-exact\");\n    q\n}\n\n/// fattn-common.cuh:64 — the admission, conjunct for conjunct.\nfn prefill_f16(max_kv: usize, n_queries: usize, k_len: usize, k: KvType, v: KvType) -> bool {\n    max_kv > 0 && n_queries > 8 && k_len <= max_kv && k == v && is_quantized(k)\n}\n\n/// fattn-mma-f16.cuh:2133+2151-2152 — the refusal rides FIRST, so the two\n/// routes can never both hold for one call.\nfn mma_kv_native_supported(\n    max_kv: usize,\n    n_queries: usize,\n    k_len: usize,\n    k: KvType,\n    v: KvType,\n) -> bool {\n    if prefill_f16(max_kv, n_queries, k_len, k, v) {\n        return false;\n    }\n    k == v && is_quantized(k) // the in-place decode surface (fixture-shrunk)\n}\n\n/// fattn.cu:583-587 get_alloc_size — either route: nothing to reserve\n/// beyond dst; the legacy shape reserves K + V f16 behind dst.\nfn f16_reserved_beyond_dst(\n    max_kv: usize,\n    n_queries: usize,\n    k_len: usize,\n    k: KvType,\n    v: KvType,\n) -> usize {\n    if mma_kv_native_supported(max_kv, n_queries, k_len, k, v)\n        || prefill_f16(max_kv, n_queries, k_len, k, v)\n    {\n        0\n    } else if is_quantized(k) {\n        2 * k_len\n    } else {\n        0 // f16 K/V needs no conversion copies at all\n    }\n}\n\n/// fattn-common.cuh:1022 — need_f16_K && !prefill_f16: the reserve fetch\n/// is negated while the pool route is armed (the copies come from the\n/// pool, :1044).\nfn f16_extra_from_reserve(\n    max_kv: usize,\n    n_queries: usize,\n    k_len: usize,\n    k: KvType,\n    v: KvType,\n    need_f16_k: bool,\n) -> bool {\n    need_f16_k && !prefill_f16(max_kv, n_queries, k_len, k, v)\n}\n\nstruct CallLedger {\n    pool_cells: usize,        // K + V pool allocations this call\n    conversion_passes: usize, // full-cache dequant passes this call\n}\n\nfn call(max_kv: usize, n_queries: usize, k_len: usize, k: KvType, v: KvType) -> CallLedger {\n    if prefill_f16(max_kv, n_queries, k_len, k, v) {\n        CallLedger {\n            pool_cells: 2 * k_len, // ggml_nelements(K) + ggml_nelements(V)\n            conversion_passes: 1,  // ONE pass, amortized across the batch\n        }\n    } else {\n        CallLedger {\n            pool_cells: 0,\n            conversion_passes: 0,\n        } // in-place read\n    }\n}\n\n#[test]\nfn the_pool_copy_is_sized_by_actual_cells_and_nothing_is_reserved() {\n    let c = call(128, PREFILL_Q, USED_KV, KvType::Q4_0, KvType::Q4_0);\n    assert_eq!(\n        c.pool_cells,\n        2 * USED_KV,\n        \"pool sized by the ACTUAL cell count\"\n    );\n    assert_eq!(c.pool_cells, 192);\n    assert_eq!(c.conversion_passes, 1);\n    // a fraction of the cap-sized naive reserve (2 x CTX = 1024)\n    assert!(c.pool_cells * 5 < 2 * CTX);\n    // nothing reserved beyond dst on EITHER route (fattn.cu:583-587)\n    assert_eq!(\n        f16_reserved_beyond_dst(128, PREFILL_Q, USED_KV, KvType::Q4_0, KvType::Q4_0),\n        0\n    );\n    assert_eq!(\n        f16_reserved_beyond_dst(128, 1, USED_KV, KvType::Q4_0, KvType::Q4_0),\n        0\n    );\n    // the reserve fetch is negated while the route is armed\n    assert!(!f16_extra_from_reserve(\n        128,\n        PREFILL_Q,\n        USED_KV,\n        KvType::Q4_0,\n        KvType::Q4_0,\n        true\n    ));\n}\n\n#[test]\nfn one_pass_amortizes_the_batch_and_decode_stays_in_place() {\n    let pre = call(128, PREFILL_Q, USED_KV, KvType::Q4_0, KvType::Q4_0);\n    assert_eq!(pre.conversion_passes, 1, \"ONE pass for the whole batch\");\n    assert_eq!(pre.pool_cells, 2 * USED_KV);\n    for _ in 0..DECODE_STEPS {\n        let d = call(128, 1, USED_KV, KvType::Q4_0, KvType::Q4_0);\n        assert_eq!(d.conversion_passes, 0, \"decode reads in place\");\n        assert_eq!(d.pool_cells, 0);\n    }\n    // the converted read returns the SAME bits as the in-place dequant\n    for cell in 0..USED_KV {\n        for i in 0..NQ {\n            assert_eq!(\n                f16_store(dequant(cell, i)).to_bits(),\n                dequant(cell, i).to_bits()\n            );\n        }\n    }\n}\n\n#[test]\nfn the_routes_are_disjoint_and_every_refusal_arm_holds() {\n    let q4 = KvType::Q4_0;\n    let q8 = KvType::Q8_0;\n    for &nq in &[1usize, 2, 8, 9, 16, 33] {\n        for &klen in &[96usize, 128] {\n            let armed = prefill_f16(128, nq, klen, q4, q4);\n            let inplace = mma_kv_native_supported(128, nq, klen, q4, q4);\n            assert!(!(armed && inplace), \"disjoint at nq={nq} klen={klen}\");\n        }\n    }\n    // one assert per admission conjunct:\n    assert!(!prefill_f16(0, 16, 96, q4, q4), \"max_kv = 0: off by default\");\n    assert!(!prefill_f16(128, 8, 96, q4, q4), \"8 queries: the boundary is > 8\");\n    assert!(\n        !prefill_f16(128, 16, 129, q4, q4),\n        \"cache over the N ceiling: the budget knob refuses\"\n    );\n    assert!(\n        !prefill_f16(128, 16, 96, q4, q8),\n        \"K-type != V-type: one converter serves one type\"\n    );\n    assert!(\n        !prefill_f16(128, 16, 96, KvType::F16, KvType::F16),\n        \"non-quantized K: nothing to convert\"\n    );\n    // the legacy-reserve shape exists exactly when NEITHER route holds:\n    // mismatched types fall back to reserved f16 copies behind dst\n    assert_eq!(f16_reserved_beyond_dst(128, 16, 96, q4, q8), 2 * 96);\n    // ...and small-query calls keep their in-place read\n    assert!(mma_kv_native_supported(128, 1, 96, q4, q4));\n}\n".to_string(),
        },
        // ── D: a ratio rule proven in one dtype branch of a kernel-choice
        // ladder transfers to its sibling unless a measured reason says
        // otherwise — the quantized branch's missing GQA rule picked the
        // vector kernel at every context length — and the widening carries
        // the IN-PLACE precondition (kv_native_supported), because without
        // it the 'fast' kernel converts the whole cache to f16 on every
        // call. Measure-only switches never ship. ──
        KernelRule {
            rule_id: "dtype-branch-dispatch-parity-in-place-precondition".to_string(),
            gpu_concept: "MECHANISM (sibling-branch dispatch parity + the in-place precondition; category D — dispatch admission correctness): a kernel-choice ladder branches by K/V dtype (here F16 vs quantized), and a measured admission rule proven in ONE branch is presumed to transfer to its SIBLING — the burden is a measured reason for divergence, never silent absence; and the widening carries an IN-PLACE PRECONDITION, because the fast kernel's win is conditional on reading its operands in place. THE PARITY SOURCE — the F16 branch's own rule, verbatim (fattn.cu:495): 'if (cc >= GGML_CUDA_CC_ADA_LOVELACE && Q->ne[1] == 1 && Q->ne[3] == 1 && !(gqa_ratio > 4 && K->ne[1] >= 8192)) { return BEST_FATTN_KERNEL_VEC; }' — above GQA 4 at long context the vector kernel loses even at one query. THE QUANTIZED BRANCH LACKED IT: pre-fix it took the vector kernel for every 1-2-query call at every context length, in the commit's words 'the vector kernel was picked for 1 and 2 queries at every context length' — on the league-model-family lane (Ternary Bonsai 2 27B PTQ1_0, head 256, GQA 6, q4_0 K/V mean-centered, RTX 4070 12 GB, greedy decode, one slot) the paired rows read depth 32768: 44.8 -> 54.2 tok/s no-MTP, 53.3 -> 84.0 draft-mtp n-max 1; depth 120000: 25.3 -> 41.2, 23.2 -> 68.5 — 1.21x to 2.95x left on the table at long context (computed from the commit's own rows), while 'draft-mtp n-max 2 (3 queries, already on the MMA kernel) and depth 0 are unchanged.' and 'llama-bench pp1/pp2 at depth 2048..16384 shows the MMA kernel is not slower from 2k keys on.' — the crossover, not a blanket MMA win, is what the rule encodes. THE LANDED FORM carries both the parity and its precondition, verbatim (fattn.cu:492-505, the quantized branch on Ada): 'if (Q->ne[1] <= 2 && (gqa_ratio <= 4 || !ggml_cuda_fattn_mma_kv_native_supported(dst))) { return BEST_FATTN_KERNEL_VEC; }' with the comment: '// Above GQA 4 the MMA kernel is faster on Ada (same rule as for F16 K/V above), but only when it reads K/V in place.' + '// Otherwise it converts the whole cache to f16 on every call, so keep the vector kernel.' THE PRECONDITION'S OWN WORDS, verbatim (the third commit): 'The GQA > 4 route to the MMA kernel on Ada only reads q4_0 and q8_0 K/V in place for head size 128 and 256 with equal K and V types. For other cases the MMA path converts the whole cache to f16 on every call. Check ggml_cuda_fattn_mma_kv_native_supported() before leaving the vector kernel.' — without the check the 'fast' route dequantizes the WHOLE cache on EVERY decode call and loses exactly where it was supposed to win. THE MEASURED-BEFORE-LANDED ARC: the PR measured with temporary switches (GGML_CUDA_FATTN_GQA_MMA / GGML_CUDA_FATTN_VEC_MAXQ), REMOVED them in its second commit, and landed the predicate with its precondition — measure-only knobs never ship. Correctness rode along: 'test-backend-ops FLASH_ATTN_EXT passes (2994/2994)... (3006/3006)' with 12 extra local cases. DECISION CONTENT: (a) sibling branches of one dispatcher (here F16 vs quantized K/V of the same kernel-choice ladder) must carry PARITY on measured admission rules — a ratio rule proven in one branch is presumed to transfer to its siblings; the burden is a measured reason for divergence, never silent absence; (b) the parity widening carries an IN-PLACE PRECONDITION: the fast kernel must read its operands in place (ggml_cuda_fattn_mma_kv_native_supported: q4_0/q8_0, head 128/256, K-type==V-type) — otherwise the 'fast' route converts the WHOLE cache to f16 on EVERY CALL and loses; (c) the measured-before-landed arc: measure with temporary switches, remove them in the same PR, land the predicate with its precondition — measure-only knobs never ship. CLASS SIGNATURE: a kernel-choice predicate whose sibling dtype branch lacks a rule the measured branch has. REGIME: multi-branch dispatchers (dtype/arch sub-ladders) with kernel pairs whose crossover depends on a shape ratio (GQA, aspect) + in-place readability preconditions. ANTI-REGIME: branches with genuinely different kernel geometry (no parity presumption); widening without the in-place check (the per-call full-cache conversion anti-case); shipping the measure switches. KINSHIP (do not double-count): dispatcher-eligibility-predicate-lags-kernel-capability (B103, entries_gpu_16) is the nearest neighbor and its DELTA is the finding shape: THERE a stale conjunct DELETES (the kernel always served the shape — fix = delete the conjunct + a positive engagement canary); HERE the rule is ABSENT in one branch and the fix ADDS the parity rule + its precondition; B103's PrismML riders (Batches 116/204/225) are surface-vs-predicate drift in the claim-wider / pairing-migration / surface-reduction directions — none is a sibling-branch parity debt. fa-fast-path-validated-exact-shape-admission-v-as-strided-view (B208, entries_gpu_78) owns the ADMISSION ALLOWLIST family (exact-shape widening + view/dtype aliasing conjuncts + the compiled-set mirror + the probe-shape-class rider); THIS is branch-parity + in-place precondition on the kernel CHOICE ladder — no allowlist, no view conditions. Corpus greps for 'gqa|parity|vector kernel|mma': the gqa hits route to gqa-kv-head-sharing-bandwidth-reduction (gpu_01, KV bandwidth sharing) + derive-params-from-global-invocation-id (gpu_02, in-kernel GQA mapping) + the warp-shuffle rider's GQA=8 simd_sum cost note — no dispatch-parity owner; the 'parity' hits route to exact-op-parity-for-analytic-backward (gpu_04, forward/backward op parity) and entrypoint-variants-share-layer-body (gpu_05, variant body sharing with a stated parity class); the 'mma' hits route to the MMA compute/instantiation family (magic-anchor-mma-exact-int-float-ffma-epilogue + signed-trit-remap-single-mma-bias-fold (gpu_106), subbyte-preexpand-int8-tile-reuses-validated-mma-consumer (gpu_100), the mma-fragment-layout + accumulator rules) — zero owners of sibling-branch dispatch parity + in-place precondition. NotBenchable here (the 4070 rows are source-reported on THEIR silicon + lane — provenance, never our bar; the decision content is the parity+precondition law). Source: PrismML-Eng/llama.cpp @ ec1ee3abede9d6fc0b7e593aa4014e599508c51a #307 (MIT, prism tag prism-b10787-73bfe6c) — ggml/src/ggml-cuda/fattn.cu:492-505 + ggml/src/ggml-cuda/fattn-mma-f16.cuh:2133-2152 (kv_native_supported) at the pin. Batch 261 / Plan 265 / Research 297.".to_string(),
            ref_shape: "// naive: the quantized branch of the kernel-choice ladder lacks the ratio\n// rule its F16 sibling carries — every 1-2-query call takes the vector\n// kernel at EVERY context length, where the F16 branch already keeps the\n// MMA kernel above GQA 4 at long context. The cost model is FIXTURE-LOCAL\n// (labeled; not the source's silicon): the vector kernel walks the cache\n// once per GQA head; the MMA kernel pays a fixed ramp + one shared walk.\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Kernel {\n    Vec,\n    Mma,\n}\n\nconst ADA: bool = true; // cc >= GGML_CUDA_CC_ADA_LOVELACE (fixture posture)\nconst GQA: u32 = 6; // the league family's ratio (head 256)\n\n/// fattn.cu:495 — the F16 branch's own rule (the parity source).\nfn f16_branch_pick(one_query: bool, batch_one: bool, gqa_ratio: u32, k_len: usize) -> Kernel {\n    if ADA && one_query && batch_one && !(gqa_ratio > 4 && k_len >= 8192) {\n        Kernel::Vec\n    } else {\n        Kernel::Mma\n    }\n}\n\n/// the quantized branch BEFORE the fix: 1-2 queries take the vector kernel\n/// unconditionally — no GQA escape, no context dependence.\nfn quantized_pick_naive(n_q: usize, _gqa_ratio: u32, _k_len: usize) -> Kernel {\n    if n_q <= 2 {\n        Kernel::Vec\n    } else {\n        Kernel::Mma\n    }\n}\n\n/// fixture-local cost model: vec = k_len * gqa (per-head walks); mma =\n/// 1024 fixed ramp + 2 * k_len (one shared walk). Crossover: 6k = 2k +\n/// 1024 at k = 256; the source measured MMA 'not slower from 2k keys on'\n/// — the model's crossover sits below that, consistently.\nfn cost(kernel: Kernel, k_len: usize, gqa_ratio: u32) -> f64 {\n    match kernel {\n        Kernel::Vec => k_len as f64 * gqa_ratio as f64,\n        Kernel::Mma => 1024.0 + 2.0 * k_len as f64,\n    }\n}\n\n#[test]\nfn the_quantized_branch_picks_vec_at_every_context_length() {\n    for &k_len in &[512usize, 2048, 32768, 120_000] {\n        assert_eq!(\n            quantized_pick_naive(1, GQA, k_len),\n            Kernel::Vec,\n            \"1 query: the vector kernel at every context length\"\n        );\n    }\n    // the F16 sibling at the SAME shapes (1 query, GQA 6) already keeps\n    // the MMA kernel at long context — the branches disagree where both\n    // serve\n    assert_eq!(f16_branch_pick(true, true, GQA, 120_000), Kernel::Mma);\n    assert_eq!(f16_branch_pick(true, true, GQA, 32768), Kernel::Mma);\n    // ...and agrees with the naive pick only below its own 8192 guard\n    assert_eq!(f16_branch_pick(true, true, GQA, 512), Kernel::Vec);\n}\n\n#[test]\nfn the_missing_rule_costs_at_long_context_in_the_model() {\n    let vec_cost = cost(Kernel::Vec, 120_000, GQA);\n    let mma_cost = cost(Kernel::Mma, 120_000, GQA);\n    assert_eq!(vec_cost, 720_000.0);\n    assert_eq!(mma_cost, 241_024.0);\n    let ratio = vec_cost / mma_cost;\n    assert!(ratio > 2.9, \"the slow pick costs ~{ratio}x at long context\");\n    // the unchanged faces the commit records: 3 queries were already on\n    // the MMA kernel (draft-mtp n-max 2), and depth 0 stays on vec for\n    // both branches\n    assert_eq!(quantized_pick_naive(3, GQA, 120_000), Kernel::Mma);\n    assert_eq!(quantized_pick_naive(1, GQA, 0), Kernel::Vec);\n    assert_eq!(f16_branch_pick(true, true, GQA, 0), Kernel::Vec);\n}\n\n#[test]\nfn the_naive_pick_is_only_correct_below_the_model_crossover() {\n    // at kv=128 the vector kernel genuinely wins the model — the defect\n    // is not the pick itself, it is the pick's CONTEXT-INDEPENDENCE\n    assert!(cost(Kernel::Vec, 128, GQA) < cost(Kernel::Mma, 128, GQA));\n    assert_eq!(cost(Kernel::Vec, 256, GQA), cost(Kernel::Mma, 256, GQA));\n    // from there up, every naive 1-query pick at GQA 6 leaves the MMA\n    // kernel's win on the table\n    for &k_len in &[512usize, 2048, 32768, 120_000] {\n        assert!(cost(Kernel::Vec, k_len, GQA) > cost(Kernel::Mma, k_len, GQA));\n    }\n}\n".to_string(),
            opt_pattern: "// optimized: the quantized branch carries its sibling's ratio rule WITH\n// the in-place precondition — above GQA 4 the MMA kernel takes the call\n// only when mma_kv_native_supported() holds (q4_0/q8_0 K/V, head 128/256,\n// K-type == V-type: the in-place readability surface); otherwise the\n// vector kernel keeps the call, because the 'fast' route would convert\n// the whole cache to f16 on EVERY call. The F16 branch is unchanged (the\n// parity source); the landed predicate carries no measure-only switches.\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Kernel {\n    Vec,\n    Mma,\n}\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum KvType {\n    F16,\n    Q4_0,\n    Q8_0,\n}\n\nconst ADA: bool = true;\nconst GQA: u32 = 6;\n\n/// the in-place readability surface (fattn-mma-f16.cuh:2133-2152,\n/// fixture-shrunk): q4_0/q8_0 only, head 128/256 only, equal K/V types.\nfn mma_kv_native_supported(k: KvType, v: KvType, head_dim: usize) -> bool {\n    let dtype_ok = matches!(k, KvType::Q4_0 | KvType::Q8_0);\n    let head_ok = head_dim == 128 || head_dim == 256;\n    dtype_ok && head_ok && k == v\n}\n\n/// fattn.cu:495 — the F16 branch's rule (unchanged; the parity source).\nfn f16_branch_pick(one_query: bool, batch_one: bool, gqa_ratio: u32, k_len: usize) -> Kernel {\n    if ADA && one_query && batch_one && !(gqa_ratio > 4 && k_len >= 8192) {\n        Kernel::Vec\n    } else {\n        Kernel::Mma\n    }\n}\n\n/// fattn.cu:492-505 — the landed quantized branch: the ratio rule WITH\n/// its in-place precondition.\nfn quantized_pick(n_q: usize, gqa_ratio: u32, k: KvType, v: KvType, head_dim: usize) -> Kernel {\n    if n_q <= 2 && (gqa_ratio <= 4 || !mma_kv_native_supported(k, v, head_dim)) {\n        Kernel::Vec\n    } else {\n        Kernel::Mma\n    }\n}\n\n/// fixture-local cost model (identical to ref_shape's).\nfn cost(kernel: Kernel, k_len: usize, gqa_ratio: u32) -> f64 {\n    match kernel {\n        Kernel::Vec => k_len as f64 * gqa_ratio as f64,\n        Kernel::Mma => 1024.0 + 2.0 * k_len as f64,\n    }\n}\n\n#[test]\nfn the_parity_rule_moves_the_long_context_pick_to_mma() {\n    // 1 and 2 queries at GQA 6, q4_0/q4_0, head 256: MMA at long context\n    assert_eq!(\n        quantized_pick(1, GQA, KvType::Q4_0, KvType::Q4_0, 256),\n        Kernel::Mma\n    );\n    assert_eq!(\n        quantized_pick(2, GQA, KvType::Q4_0, KvType::Q4_0, 256),\n        Kernel::Mma\n    );\n    // draft-mtp n-max 2's successor (3 queries) was already on MMA —\n    // unchanged\n    assert_eq!(\n        quantized_pick(3, GQA, KvType::Q4_0, KvType::Q4_0, 256),\n        Kernel::Mma\n    );\n    // SIBLING PARITY: the branches now agree at the same shape\n    assert_eq!(f16_branch_pick(true, true, GQA, 120_000), Kernel::Mma);\n}\n\n#[test]\nfn the_in_place_precondition_keeps_vec_where_mma_would_convert() {\n    // head 64: outside the validated in-place surface — the MMA route\n    // would convert the whole cache to f16 on every call, so the vector\n    // kernel keeps the call even at GQA 6 long context\n    assert_eq!(\n        quantized_pick(1, GQA, KvType::Q4_0, KvType::Q4_0, 64),\n        Kernel::Vec\n    );\n    // K-type != V-type: the same refusal\n    assert_eq!(\n        quantized_pick(1, GQA, KvType::Q4_0, KvType::Q8_0, 256),\n        Kernel::Vec\n    );\n    // F16 K/V is not this branch's in-place surface either\n    assert!(!mma_kv_native_supported(KvType::F16, KvType::F16, 256));\n    // ...and the precondition never flips a shape the ratio rule does not\n    // cover: GQA 4 stays on vec at every head dim\n    assert_eq!(quantized_pick(1, 4, KvType::Q4_0, KvType::Q4_0, 256), Kernel::Vec);\n    assert_eq!(quantized_pick(1, 4, KvType::Q4_0, KvType::Q4_0, 128), Kernel::Vec);\n}\n\n#[test]\nfn the_second_validated_surface_takes_mma_too() {\n    // head 128 + q8_0/q8_0 is inside the validated in-place surface\n    assert!(mma_kv_native_supported(KvType::Q8_0, KvType::Q8_0, 128));\n    assert_eq!(\n        quantized_pick(1, GQA, KvType::Q8_0, KvType::Q8_0, 128),\n        Kernel::Mma\n    );\n    // and the model, at the shapes the widened rule newly routes to MMA:\n    // not slower from the crossover up (source-measured 'not slower from\n    // 2k keys on'; model crossover 256)\n    for &k_len in &[2048usize, 32768, 120_000] {\n        assert!(cost(Kernel::Mma, k_len, GQA) <= cost(Kernel::Vec, k_len, GQA));\n    }\n}\n".to_string(),
        },
    ]
}
